#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    vector<long long> a(n);
    for (auto &x : a) scanf("%lld", &x);
    long long total = accumulate(a.begin(), a.end(), 0LL), answer = llabs(total);
    // Negating x changes the sum to total - 2x.
    for (long long x : a) answer = min(answer, llabs(total - 2 * x));
    printf("%lld\n", answer);
}

import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer st = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        st.nextToken();
        int n = (int) st.nval;
        long[] a = new long[n];
        long total = 0;
        for (int i = 0; i < n; i++) { st.nextToken(); a[i] = (long) st.nval; total += a[i]; }
        long answer = Math.abs(total);
        // Negating x changes the sum to total - 2x.
        for (long x : a) answer = Math.min(answer, Math.abs(total - 2 * x));
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func abs(x int) int {
	if x < 0 {
		return -x
	}
	return x
}

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	nextInt := func() int { sc.Scan(); v, _ := strconv.Atoi(sc.Text()); return v }
	n := nextInt()
	a := make([]int, n)
	total := 0
	for i := range a {
		a[i] = nextInt()
		total += a[i]
	}
	answer := abs(total)
	// Negating x changes the sum to total - 2x.
	for _, x := range a {
		answer = min(answer, abs(total-2*x))
	}
	fmt.Println(answer)
}
